    # 键序：会话、状态、时刻、期限、池、地址、租期；会话/状态/池/地址为
    # str，余为 int；挂起时池/地址为 ""、期限与租期为 0。
    payload = {
        "会话": sid,
        "状态": state,
        "时刻": now_ms,
        "期限": deadline,
        "池": pool_id,
        "地址": address,
        "租期": lease,
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

