    return json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"

@staticmethod
def _render_takeover(
    old,
    old_address,
    old_deadline,
    old_lease,
    sid,
    now_ms,
    deadline,
    pool_id,
    address,
    lease,
):
